Object.assign(english,{muchalindaConceptCaption:"Conceptual illustration, not a record of current conditions"});
const thai={};
document.querySelectorAll("[data-i18n]").forEach(el=>thai[el.dataset.i18n]=el.innerHTML);
const translations={th:thai,lo:lao,en:english};
const searchPlaceholders={th:"ค้นหาเรื่องราว โครงการ หรือกิจกรรม",lo:"ຄົ້ນຫາເລື່ອງລາວ ໂຄງການ ຫຼືກິດຈະກຳ",en:"Search stories, projects, or activities"};
const searchLabels={th:"ค้นหาในเว็บไซต์",lo:"ຄົ້ນຫາໃນເວັບໄຊ",en:"Search this website"};
const titles={
  th:"รุ่นทดลอง — พระธาตุพนม สู่มรดกโลก",
  lo:"ສະບັບທົດລອງ — ພະທາດພະນົມສູ່ມໍລະດົກໂລກ",
  en:"Trial — Phra That Phanom to World Heritage"
};
let lang=localStorage.getItem("site-language");
if(!translations[lang])lang="th";
function setLanguage(nextLang){
  lang=translations[nextLang]?nextLang:"th";
  document.documentElement.lang=lang;
  document.querySelectorAll("[data-i18n]").forEach(el=>{
    const key=el.dataset.i18n;
    el.innerHTML=translations[lang][key]||thai[key];
  });
  document.querySelectorAll(".language-option").forEach(button=>{
    const active=button.dataset.lang===lang;
    button.classList.toggle("active",active);
    button.setAttribute("aria-selected",String(active));
  });
  const languageLabel=document.getElementById("currentLanguageLabel");
  if(languageLabel)languageLabel.textContent={th:"ไทย",lo:"ລາວ",en:"English"}[lang];
  document.title=titles[lang];
  const searchInput=document.getElementById("siteSearchInput");
  if(searchInput){searchInput.placeholder=searchPlaceholders[lang];searchInput.setAttribute("aria-label",searchLabels[lang]);}
  localStorage.setItem("site-language",lang);
}
document.querySelectorAll(".language-option").forEach(button=>button.addEventListener("click",()=>setLanguage(button.dataset.lang)));
const languageDropdown=document.getElementById("languageDropdown");
const languageDropdownButton=document.getElementById("languageDropdownButton");
const languageMenu=document.getElementById("languageMenu");
function setLanguageMenuOpen(open){
  if(!languageDropdownButton||!languageMenu)return;
  languageDropdownButton.setAttribute("aria-expanded",String(open));
  languageMenu.hidden=!open;
}
languageDropdownButton?.addEventListener("click",event=>{
  event.stopPropagation();
  setLanguageMenuOpen(languageDropdownButton.getAttribute("aria-expanded")!=="true");
});
document.querySelectorAll(".language-option").forEach(button=>button.addEventListener("click",()=>setLanguageMenuOpen(false)));
document.addEventListener("click",event=>{if(languageDropdown&&!languageDropdown.contains(event.target))setLanguageMenuOpen(false)});
document.addEventListener("keydown",event=>{if(event.key==="Escape")setLanguageMenuOpen(false)});
setLanguage(lang);
const progressBar=document.getElementById("progressBar");addEventListener("scroll",()=>{const max=document.documentElement.scrollHeight-innerHeight;progressBar.style.width=(max>0?scrollY/max*100:0)+"%"},{passive:true});
const shareButton=document.getElementById("shareButton"),toast=document.getElementById("toast");
const shareText={th:"พระธาตุพนม สู่มรดกโลก",lo:"ພະທາດພະນົມສູ່ມໍລະດົກໂລກ",en:"Phra That Phanom to World Heritage"};
const copiedText={th:"คัดลอกลิงก์แล้ว",lo:"ຄັດລອກລິ້ງແລ້ວ",en:"Link copied"};
const shareErrorText={th:"ไม่สามารถแบ่งปันได้",lo:"ບໍ່ສາມາດແບ່ງປັນໄດ້",en:"Unable to share"};
shareButton.addEventListener("click",async()=>{
  const data={title:document.title,text:shareText[lang],url:location.href};
  try{
    if(navigator.share)await navigator.share(data);
    else{await navigator.clipboard.writeText(location.href);showToast(copiedText[lang]);}
  }catch(e){if(e.name!=="AbortError")showToast(shareErrorText[lang]);}
});
function showToast(message){toast.textContent=message;toast.classList.add("show");setTimeout(()=>toast.classList.remove("show"),2200)}

const siteSearchForm=document.getElementById("siteSearchForm");
const siteSearchInput=document.getElementById("siteSearchInput");
const searchableSections=["projects","history","milestones","world-heritage","videos","project-resources","media-library","news-events","documents","donation","community"]
  .map(id=>document.getElementById(id)).filter(Boolean);
const noSearchResult={th:"ไม่พบหัวข้อที่ค้นหา",lo:"ບໍ່ພົບຫົວຂໍ້ທີ່ຄົ້ນຫາ",en:"No matching section found"};
if(siteSearchForm&&siteSearchInput){
  siteSearchForm.addEventListener("submit",event=>{
    event.preventDefault();
    const query=siteSearchInput.value.trim().toLocaleLowerCase(lang);
    if(!query){siteSearchInput.focus();return;}
    const target=searchableSections.find(section=>section.textContent.toLocaleLowerCase(lang).includes(query));
    if(!target){showToast(noSearchResult[lang]);return;}
    target.scrollIntoView({behavior:matchMedia("(prefers-reduced-motion: reduce)").matches?"auto":"smooth",block:"start"});
    const highlightTarget=target.closest(".feed-column>section")||target;
    highlightTarget.classList.remove("search-highlight");
    requestAnimationFrame(()=>highlightTarget.classList.add("search-highlight"));
    setTimeout(()=>highlightTarget.classList.remove("search-highlight"),1800);
  });
}

const navigationLinks=[...document.querySelectorAll("[data-nav-target]")];
const trackedSections=["top","projects","history","milestones","world-heritage","videos","project-resources","community"]
  .map(id=>document.getElementById(id)).filter(Boolean);
let navigationFrame=0;
function updateActiveNavigation(){
  navigationFrame=0;
  const marker=window.scrollY+Math.min(220,window.innerHeight*.3);
  let activeId="top";
  trackedSections.forEach(section=>{if(section.id!=="top"&&section.offsetTop<=marker)activeId=section.id;});
  navigationLinks.forEach(link=>link.classList.toggle("active",link.dataset.navTarget===activeId));
}
addEventListener("scroll",()=>{if(!navigationFrame)navigationFrame=requestAnimationFrame(updateActiveNavigation);},{passive:true});
addEventListener("resize",updateActiveNavigation);
updateActiveNavigation();

const scrollToTopButton=document.getElementById("scrollToTopButton");
const scrollToBottomButton=document.getElementById("scrollToBottomButton");
if(scrollToTopButton&&scrollToBottomButton){
  const scrollBehavior=()=>matchMedia("(prefers-reduced-motion: reduce)").matches?"auto":"smooth";
  const updatePageNavigation=()=>{
    const scrollBottom=window.scrollY+window.innerHeight;
    scrollToTopButton.disabled=window.scrollY<12;
    scrollToBottomButton.disabled=scrollBottom>=document.documentElement.scrollHeight-12;
  };
  scrollToTopButton.addEventListener("click",()=>window.scrollTo({top:0,behavior:scrollBehavior()}));
  scrollToBottomButton.addEventListener("click",()=>window.scrollTo({top:document.documentElement.scrollHeight,behavior:scrollBehavior()}));
  addEventListener("scroll",updatePageNavigation,{passive:true});
  addEventListener("resize",updatePageNavigation);
  new MutationObserver(updatePageNavigation).observe(document.body,{childList:true,subtree:true});
  updatePageNavigation();
}

// Project-first navigation: project names live at the side on large screens and
// at the bottom on smaller screens. The top bar is reserved for child nodes of
// the currently open project.
(()=>{
  const topNav=document.querySelector(".social-topbar .top-nav");
  const sideNav=document.querySelector(".desktop-sidebar .social-nav");
  const bottomNav=document.querySelector(".mobile-bottom-nav");
  const catalog=document.getElementById("projectCatalogGrid");
  if(!topNav||!sideNav||!bottomNav||!catalog)return;

  const worldTabs=[
    ["#top","top","หน้าหลัก"],
    ["#history","history","เรื่องราวแห่งศรัทธา"],
    ["#milestones","milestones","หมุดหมายสำคัญ"],
    ["#world-heritage","world-heritage","คุณค่าโดดเด่นเป็นสากล"],
    ["#videos","videos","วิดีโอ"],
    ["#project-resources","project-resources","ข้อมูลโครงการ"],
    ["#community","community","ชุมชน"]
  ];
  const muchalindaTabs=[
    ["#muchalinda-overview","muchalinda-overview","ภาพรวมโครงการ"],
    ["#muchalinda-history","muchalinda-history","ความเป็นมา"],
    ["#muchalinda-objectives","muchalinda-objectives","วัตถุประสงค์"],
    ["#muchalinda-progress","muchalinda-progress","ความคืบหน้า"],
    ["#muchalinda-donation","muchalinda-donation","ร่วมบุญกับโครงการ"]
  ];
  let activeProject="พระธาตุพนม สู่มรดกโลก";
  let activeTabs=worldTabs;
  const projectTabsByTitle=new Map();
  let projectRenderQueued=false;

  function isMuchalinda(title){return /muchalinda|mujalin|มุจลิน/i.test(title||"")}
  function isWorldHeritage(title){return /มรดกโลก|world heritage/i.test(title||"")&&!isMuchalinda(title)}
  function iconFor(index){return `<span class="project-switch-icon" aria-hidden="true">${index+1}</span>`}

  function renderTopTabs(tabs=worldTabs){
    activeTabs=tabs;
    const sig = tabs.map(t=>t.join(":")).join("|");
    if(topNav.dataset.renderedSig === sig && topNav.children.length > 0) return;
    topNav.dataset.renderedSig = sig;
    topNav.replaceChildren();
    topNav.classList.add("project-node-tabs");
    tabs.forEach(([href,target,label],index)=>{
      const link=document.createElement("a");
      link.href=href;
      link.dataset.navTarget=target;
      link.className=index===0?"active":"";
      link.textContent=label;
      topNav.append(link);
    });
    topNav.hidden=tabs.length===0;
  }

  function projectCards(){
    return [...catalog.querySelectorAll(".project-catalog-card")].map(card=>({
      card,
      title:card.querySelector("h3")?.textContent?.trim()||"โครงการ",
      open:card.querySelector(".project-card-open")
    }));
  }

  function closeProjectDetails(){
    document.body.classList.remove("support-project-open");
    const support=document.getElementById("muchalinda-project");
    const selected=document.getElementById("selectedProjectDetail");
    if(support)support.hidden=true;
    if(selected)selected.hidden=true;
  }

  function syncTopTabsFromSelectedProject(){
    const configuredTabs=projectTabsByTitle.get(activeProject);
    if(document.body.classList.contains("support-project-open")){
      renderTopTabs(configuredTabs?.length?configuredTabs:muchalindaTabs);
      return;
    }
    if(configuredTabs?.length){
      renderTopTabs(configuredTabs);
      return;
    }
    if(isWorldHeritage(activeProject)){
      renderTopTabs(worldTabs);
      return;
    }
    const links=[...document.querySelectorAll("#selectedProjectLinks a")].map((link,index)=>[
      link.getAttribute("href")||"#top",
      `project-node-${index}`,
      link.textContent.trim()||"ดูรายละเอียด"
    ]);
    renderTopTabs(links);
  }

  function activateProject(title){
    activeProject=title;
    if(isWorldHeritage(title)){
      closeProjectDetails();
      syncTopTabsFromSelectedProject();
      history.replaceState(null,"","#top");
      window.scrollTo({top:0,behavior:matchMedia("(prefers-reduced-motion: reduce)").matches?"auto":"smooth"});
      renderProjectSwitchers();
      return;
    }
    const entry=projectCards().find(item=>item.title===title);
    if(!entry?.open)return;
    entry.open.click();
    setTimeout(()=>{
      syncTopTabsFromSelectedProject();
      renderProjectSwitchers();
    },0);
  }

  function makeProjectButton(title,index,compact=false){
    const button=document.createElement("button");
    button.type="button";
    button.className=`project-switch-button${compact?" compact":""}`;
    button.classList.toggle("active",title===activeProject);
    button.setAttribute("aria-current",title===activeProject?"page":"false");
    button.innerHTML=`${iconFor(index)}<span>${title}</span>`;
    button.addEventListener("click",()=>activateProject(title));
    return button;
  }

  function renderProjectSwitchers(){
    projectRenderQueued=false;
    const entries=projectCards();
    const titles=entries.length?entries.map(item=>item.title):[
      "พระธาตุพนม สู่มรดกโลก",
      "โครงการบูรณะสระมุจลินท์ (สระพังทอง)"
    ];
    const sig = `${activeProject}|` + titles.join("|");
    if(sideNav.dataset.renderedSig === sig && sideNav.children.length > 0) return;
    sideNav.dataset.renderedSig = sig;
    sideNav.replaceChildren();
    const heading=document.createElement("strong");
    heading.className="project-switch-heading";
    heading.textContent="โครงการทั้งหมด";
    sideNav.append(heading,...titles.map((title,index)=>makeProjectButton(title,index)));
    bottomNav.replaceChildren(...titles.map((title,index)=>makeProjectButton(title,index,true)));
    bottomNav.setAttribute("aria-label","เลือกโครงการ");
  }

  function queueProjectRender(){
    if(projectRenderQueued)return;
    projectRenderQueued=true;
    requestAnimationFrame(renderProjectSwitchers);
  }

  renderTopTabs(worldTabs);
  renderProjectSwitchers();
  new MutationObserver(queueProjectRender).observe(catalog,{childList:true,subtree:true});
  new MutationObserver(()=>{
    if(document.body.classList.contains("support-project-open")){
      const title=projectCards().find(item=>isMuchalinda(item.title))?.title;
      if(title)activeProject=title;
    }
    syncTopTabsFromSelectedProject();
    queueProjectRender();
  }).observe(document.body,{attributes:true,attributeFilter:["class"]});

  function nodeDestination(node,muchalinda){
    const external=/^https:\/\//i.test(node.url||"")?node.url:"";
    if(external)return external;
    const key=String(node.contentRef||node.slug||"").toLowerCase();
    if(muchalinda){
      return ({
        overview:"#muchalinda-overview",muchalindahero:"#muchalinda-overview",
        history:"#muchalinda-history",objectives:"#muchalinda-objectives",
        progress:"#muchalinda-progress",donation:"#muchalinda-donation",
        muchalindadonation:"#muchalinda-donation"
      })[key]||"#muchalinda-project";
    }
    return ({
      hero:"#top",story:"#history",storyfeature:"#history",storyart:"#history",storypeople:"#history",
      criteria:"#world-heritage",criteriaone:"#world-heritage",criteriatwo:"#world-heritage",criteriathree:"#world-heritage",
      "outstanding-value":"#world-heritage","shared-work":"#world-heritage",
      processoverview:"#world-heritage",processone:"#world-heritage",processtwo:"#world-heritage",processthree:"#world-heritage",processfour:"#world-heritage",
      milestones:"#milestones",milestoneone:"#milestones",milestonetwo:"#milestones",milestonethree:"#milestones",milestonefour:"#milestones",
      all:"#media-library",media:"#media-library",news:"#news-events",document:"#documents",documents:"#documents",donation:"#donation"
    })[key]||({news:"#news-events",document:"#documents",donation:"#donation"})[node.type]||"#projects";
  }

  async function listenForProjectTree(){
    try{
      const [{getApp,getApps,initializeApp},{getAuth,onAuthStateChanged},{collection,getFirestore,onSnapshot,orderBy,query,where},{firebaseConfig}]=await Promise.all([
        import("https://www.gstatic.com/firebasejs/10.14.1/firebase-app.js"),
        import("https://www.gstatic.com/firebasejs/10.14.1/firebase-auth.js"),
        import("https://www.gstatic.com/firebasejs/10.14.1/firebase-firestore.js"),
        import("./firebase-config.js")
      ]);
      const app=getApps().length?getApp():initializeApp(firebaseConfig);
      const auth=getAuth(app);
      const nodes=collection(getFirestore(app),"projects","world-heritage","siteNodes");
      let unsubscribe=null;
      const connect=user=>{
        if(unsubscribe)unsubscribe();
        const source=user?.email?.toLowerCase()==="jaru072@gmail.com"?query(nodes,orderBy("order","asc")):query(nodes,where("published","==",true));
        unsubscribe=onSnapshot(source,snapshot=>{
          const items=snapshot.docs.map(record=>({id:record.id,...record.data()})).filter(node=>!node.deletedAt);
          const projects=items.filter(node=>node.type==="project");
          projectTabsByTitle.clear();
          projects.forEach(project=>{
            const tabs=items
              .filter(node=>node.parentId===project.id&&node.type!=="project")
              .sort((a,b)=>(Number(a.order)||0)-(Number(b.order)||0)||String(a.title||"").localeCompare(String(b.title||""),"th"))
              .map((node,index)=>{
                const href=nodeDestination(node,isMuchalinda(project.title));
                return [href,href.startsWith("#")?href.slice(1):`project-node-${node.id||index}`,node.title||"ดูรายละเอียด"];
              });
            projectTabsByTitle.set(project.title||"โครงการ",tabs);
          });
          syncTopTabsFromSelectedProject();
        },error=>console.warn("Project navigation unavailable",error.code));
      };
      onAuthStateChanged(auth,connect);
    }catch(error){console.warn("Project navigation unavailable",error)}
  }

  listenForProjectTree();

  addEventListener("scroll",()=>{
    if(topNav.hidden)return;
    const marker=window.scrollY+Math.min(220,window.innerHeight*.3);
    let activeTarget="top";
    activeTabs.forEach(([href,target])=>{
      if(!href.startsWith("#"))return;
      const section=document.getElementById(target);
      if(section&&section.offsetTop<=marker)activeTarget=target;
    });
    topNav.querySelectorAll("[data-nav-target]").forEach(link=>link.classList.toggle("active",link.dataset.navTarget===activeTarget));
  },{passive:true});
})();
